{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const fail = (msg) => {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let names = null
const index = new Set()
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/

lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  const err = (m) => fail(`error: line ${n}: ${m}`)
  if (t[0] === 'candidates') {
    if (names !== null || ballots.length) err('candidates must be declared once, before any ballot')
    if (t.length < 2) err('expected candidates <name>...')
    names = []
    for (const nm of t.slice(1)) {
      if (!NAME.test(nm)) err(`invalid candidate name ${nm}`)
      if (index.has(nm)) err(`candidate ${nm} is declared twice`)
      index.add(nm)
      names.push(nm)
    }
  } else if (t[0] === 'ballot') {
    if (names === null) err('candidates must be declared once, before any ballot')
    if (t.length < 3) err('expected ballot <count> <candidate>...')
    if (!/^[1-9][0-9]*$/.test(t[1])) err('count must be a positive integer')
    const seen = new Set()
    for (const nm of t.slice(2)) {
      if (!index.has(nm)) err(`unknown candidate ${nm}`)
      if (seen.has(nm)) err(`candidate ${nm} is repeated`)
      seen.add(nm)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else err(`unknown directive ${t[0]}`)
})

if (names === null) fail('error: no candidates')

const continuing = new Set(names)
const history = [] // Map name -> votes per round
const out = []
let winner = null
let roundNo = 0
for (;;) {
  roundNo++
  const votes = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      votes.set(c, votes.get(c) + b.count)
      active += b.count
    }
  }
  let total = 0n
  for (const b of ballots) total += b.count
  history.push(votes)
  const listed = [...votes.entries()].sort((a, b) =>
    a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)
  let text = `round ${roundNo}: ` + listed.map(([c, v]) => `${c}=${v}`).join(' ')
  text += ` exhausted=${total - active}`
  out.push(text)
  if (active === 0n) break
  const win = listed.find(([, v]) => v * 2n > active)
  if (win) { winner = win[0]; break }
  let min = listed[listed.length - 1][1]
  let tied = listed.filter(([, v]) => v === min).map(([c]) => c)
  while (tied.length > 1) {
    let changed = false
    for (const h of history) {
      const vs = tied.map((c) => h.get(c))
      const m = vs.reduce((a, b) => (b < a ? b : a))
      if (vs.some((v) => v !== m)) {
        tied = tied.filter((c) => h.get(c) === m)
        changed = true
        break
      }
    }
    if (!changed) break
  }
  const elim = tied.reduce((a, b) => (b > a ? b : a))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner === null ? 'no winner' : `winner ${winner}`
process.stdout.write((mode === 'rounds' ? out.join('\n') + '\n' : `rounds ${roundNo}\n`) + end + '\n')
EOF
node --test test/*.test.js 2>&1 | grep -E "^# (pass|fail)"","description":"Write CLI and run tests"}

